  'fm.x.cutM': "Momento fletor na barra {el}, extremidade {end} (corte)",
  'fm.x3.reaction0': "Reação segundo x no nó {node}",
  'fm.x3.reaction1': "Reação segundo y no nó {node}",
  'fm.x3.reaction2': "Reação vertical (z) no nó {node}",
