  'dsm.explorerBtn': "⊞ Ver matriz",
  'dsm.matrixExplorer': "Matriz de rigidez — fluxo reduzido",
  'dsm.mode2dBanner2dof': 'Modo 2D — 2 GDL/nó (ux, uy) · Matrizes 4×4 (pórtico) / 4×4 (treliça)',
  'dsm.mode2dBanner3dof': 'Modo 2D — 3 GDL/nó (ux, uz, θy) · Matrizes 6×6 (pórtico) / 4×4 (treliça)',
  'dsm.mode3dBanner': 'Modo 3D — 6 GDL/nó (u, v, w, θx, θy, θz) · Matrizes 12×12 (pórtico) / 6×6 (treliça)',
  'dsm.next': 'Próximo →',
