  'dsm.step1.dofPerNode': 'GDL por nó',
  'dsm.step1.eachNodeHas': 'Cada nó tem: ',
  'dsm.step1.explanation': 'O primeiro passo é atribuir um <strong>índice global</strong> a cada grau de liberdade (GDL) da estrutura.',
  'dsm.step1.free': 'Livre',
  'dsm.step1.freeDof': 'GDL livres',
  'dsm.step1.globalIndex': 'Índice global',
  'dsm.step1.localDof': 'GDL local',
  'dsm.step1.nodeHeader': 'Nó',
  'dsm.step1.ordering': 'Os GDL <span class="free">livres</span> são numerados primeiro (0 a {nFree}), seguidos pelos <span class="restr">restringidos</span> ({nFreeStart} a {nTotal}).',
  'dsm.step1.restrained': 'Restringido',
