  'material.aluminum6061T6': 'Alumínio 6061-T6',
  'material.concreteH20': 'Concreto H-20',
  'material.concreteH25': 'Concreto H-25',
  'material.concreteH30': 'Concreto H-30',
  'material.concreteH35': 'Concreto H-35',
